<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { RouterLink, useRoute } from 'vue-router';
import { useI18n } from 'vue-i18n';
import { get, post } from '../api/client';
import { session } from '../api/session';
import { Button, Card, Field, Input, Select, EmptyState } from '../components/ui';
interface Scope { accessId: number; label: string; fromDay: string; toDay: string; channelId: string | null; model: string | null; costs: boolean; details: boolean; export: boolean; review: boolean; enabled: boolean; version: number }
interface Grant { accessId: number; email: string; acceptedAt: string | null; expiresAt: string; revokedAt: string | null; scope: Scope | null }
interface Report { scope: Scope; generatedAt: string; chargeUsd: string | null; records: number; pricedRecords: number; supplierCostUsd?: string | null; costRecords?: number; days: { day: string; scanStatus: string; sourceScope: string | null; collectedAt: string | null; records: number; pricedRecords: number; chargeUsd: string | null; costRecords?: number; supplierCostUsd?: string | null }[] }
interface Review { id: number; scopeVersion: number; report: Report; note: string; status: string; decision: string | null; version: number; createdAt: string }
interface RecordRow { id: number; day: string; model: string | null; channelId: string | null; charge: number | null; supplierCost?: number | null }
const route = useRoute(), { locale } = useI18n(), l = (zh: string, en: string) => locale.value.startsWith('zh') ? zh : en;
const canManage = computed(() => session.state.user?.role !== 'viewer' && session.state.workspaceRole === 'owner');
const manage = ref(canManage.value && (route.query.mode === 'manage' || session.state.user?.role === 'root')), busy = ref(false), error = ref(''), notice = ref('');
const sites = ref<{ id: number; label: string }[]>([]), siteId = ref<string | number | null>(null), grants = ref<Grant[]>([]), received = ref<Scope[]>([]), moreScopes = ref(false), limited = ref(false);
const selected = ref<number | null>(null), current = ref<Scope | null>(null), report = ref<Report | null>(null), reviews = ref<Review[]>([]), moreReviews = ref(false), records = ref<RecordRow[]>([]), moreRecords = ref(false), showRecords = ref(false);
const draft = ref(blank()), submitNote = ref(''), decisions = ref<Record<number, string>>({});
const base = computed(() => manage.value ? '/api/services/finance-access' : '/api/collaboration/finance');
const grant = computed(() => grants.value.find(g => g.accessId === selected.value));
const inactive = computed(() => !!grant.value && (!!grant.value.revokedAt || new Date(grant.value.expiresAt + 'Z').getTime() <= Date.now()));
const fields = computed(() => [ ['costs', l('显示上游成本', 'Show supplier costs')], ['details', l('查看消费明细', 'View consumption records')], ['export', l('导出每日汇总', 'Export daily summary')], ['review', l('提交与查看复核', 'Submit and read reviews')] ] as [ 'costs' | 'details' | 'export' | 'review', string ][]);
function blank() { const today = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10); return { label: '', fromDay: today, toDay: today, channelId: '', model: '', costs: false, details: false, export: false, review: false, enabled: true, version: 0 }; }
const amount = (v: string | number | null | undefined) => v == null ? l('未知', 'Unknown') : Number(v).toLocaleString(undefined, { maximumFractionDigits: 6 });
const labels: Record<string, [string, string]> = { missing: ['尚无采集', 'Not collected'], partial: ['部分读取', 'Partial scan'], complete: ['本轮读取完整', 'Scan complete'], pending: ['待采集', 'Pending'], error: ['采集失败', 'Collection failed'], changed: ['来源变化', 'Source changed'], unsupported: ['接口不兼容', 'Unsupported'], submitted: ['待站长复核', 'Awaiting owner review'], accepted: ['已确认', 'Accepted'], returned: ['已退回', 'Returned'], 'consumption-only': ['消费日志', 'Consumption logs'], 'consume-and-error-logs': ['消费与错误日志', 'Consumption and error logs'] };
const label = (s: string) => labels[s] ? l(...labels[s]) : s;
function clear() { selected.value = null; current.value = null; report.value = null; reviews.value = []; records.value = []; showRecords.value = false; draft.value = blank(); submitNote.value = ''; decisions.value = {}; }
async function action(fn: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await fn(); } catch (e) { error.value = e instanceof Error ? e.message : String(e); report.value = null; records.value = []; reviews.value = []; } finally { busy.value = false; } }
async function list(append = false) {
 if (manage.value) { if (!siteId.value) return; const r = await get<{ items: Grant[]; limited: boolean }>(base.value, { query: { siteId: Number(siteId.value) } }); grants.value = r.items; limited.value = r.limited; }
 else { const r = await get<{ items: Scope[]; hasMore: boolean }>(base.value, { query: { beforeId: append ? received.value.at(-1)?.accessId : undefined } }); received.value = append ? [...received.value, ...r.items] : r.items; moreScopes.value = r.hasMore; }
}
async function loadReviews(append = false) { if (!selected.value || (!manage.value && !current.value?.review)) return; const r = await get<{ items: Review[]; hasMore: boolean }>(`${base.value}/${selected.value}/reviews`, { query: { beforeId: append ? reviews.value.at(-1)?.id : undefined } }); reviews.value = append ? [...reviews.value, ...r.items] : r.items; moreReviews.value = r.hasMore; }
async function loadReport() { if (!selected.value || !current.value) return; report.value = (await get<{ report: Report }>(`${base.value}/${selected.value}/report`)).report; current.value = report.value.scope; await loadReviews(); }
async function select(accessId: number, scope: Scope | null) { await action(async () => { clear(); selected.value = accessId; current.value = scope; draft.value = scope ? { ...scope, channelId: scope.channelId ?? '', model: scope.model ?? '' } : blank(); if (scope) { if (inactive.value) await loadReviews(); else await loadReport(); } }); }
async function switchMode(value: boolean) { await action(async () => { manage.value = value; clear(); await list(); }); }
async function chooseSite(value: string | number) { await action(async () => { siteId.value = value; clear(); await list(); }); }
onMounted(() => action(async () => { if (canManage.value) { const r = await get<{ sites: { id: number; label: string }[] }>('/api/services/catalog'); sites.value = r.sites; siteId.value = sites.value.find(s => String(s.id) === route.query.site)?.id ?? sites.value[0]?.id ?? null; } await list(); }));
async function save() { await action(async () => { if (!selected.value) return; const b = { ...draft.value, channelId: draft.value.channelId.trim() || null, model: draft.value.model.trim() || null }; delete (b as Partial<Scope>).accessId; const r = await post<{ scope: Scope }>(`${base.value}/${selected.value}`, b); current.value = r.scope; draft.value.version = r.scope.version; records.value = []; showRecords.value = false; await list(); await loadReport(); notice.value = l('授权已保存。协作者仅能读取当前版本范围，旧版复核由站长留存。', 'Scope saved. Collaborators can access the current scope only; the owner retains earlier reviews.'); }); }
async function loadRecords(append = false) { await action(async () => { const r = await get<{ items: RecordRow[]; hasMore: boolean }>(`${base.value}/${selected.value}/records`, { query: { beforeId: append ? records.value.at(-1)?.id : undefined } }); records.value = append ? [...records.value, ...r.items] : r.items; moreRecords.value = r.hasMore; showRecords.value = true; }); }
async function submit() { await action(async () => { await post(`${base.value}/${selected.value}/reviews`, { version: current.value!.version, note: submitNote.value }); submitNote.value = ''; await loadReviews(); notice.value = l('已提交当时的金额与覆盖快照，等待站长复核。', 'Submitted the current amount and coverage snapshot for owner review.'); }); }
async function decide(r: Review, status: string) { await action(async () => { await post(`${base.value}/${selected.value}/reviews/${r.id}`, { version: r.version, status, decision: decisions.value[r.id] ?? '' }); await loadReviews(); }); }
async function exportCsv() { await action(async () => { const workspace = localStorage.getItem('rp-workspace'); const r = await fetch(`${base.value}/${selected.value}/report.csv`, { credentials: 'same-origin', headers: workspace ? { 'x-workspace-id': workspace } : {} }); if (!r.ok) throw new Error(`HTTP ${r.status}`); const url = URL.createObjectURL(await r.blob()), a = document.createElement('a'); a.href = url; a.download = 'shared-finance.csv'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }); }
</script>
<template>
 <div class="rp-page space-y-5">
  <div><p class="text-xs uppercase tracking-widest text-accent">FINANCE COLLABORATION</p><h1 class="mt-1 text-xl font-semibold">{{ l('财务协作', 'Finance collaboration') }}</h1><p class="mt-2 max-w-3xl text-sm leading-6 text-muted">{{ l('按站点和日期共享已有消费记录，分别控制成本、明细、导出和复核权限。金额与覆盖来自已采集日志，复核不代表付款、退款或结算。', 'Share collected consumption records by site and date, with separate cost, detail, export and review permissions. Reviews do not execute payments, refunds or settlement.') }}</p></div>
  <div class="flex flex-wrap gap-2"><Button :variant="manage ? 'outline' : 'primary'" :disabled="busy" @click="switchMode(false)">{{ l('收到的财务授权', 'Received access') }}</Button><Button v-if="canManage" :variant="manage ? 'primary' : 'outline'" :disabled="busy" @click="switchMode(true)">{{ l('管理财务授权', 'Manage access') }}</Button><RouterLink to="/collaboration" class="self-center text-sm text-accent">{{ l('接受邀请或管理协作身份', 'Accept invites or manage collaborators') }} →</RouterLink></div>
  <p v-if="error" role="alert" class="rounded border border-red/30 bg-red/10 p-3 text-sm text-red">{{ error }}</p><p v-if="notice" role="status" class="text-sm text-accent">{{ notice }}</p>
  <template v-if="manage"><Field v-if="sites.length" :label="l('当前站点', 'Current site')"><Select :model-value="siteId" :options="sites.map(s => ({ value: s.id, label: s.label }))" :disabled="busy" @update:model-value="chooseSite" /></Field><p v-else-if="!busy" class="text-sm text-muted">{{ l('只有站点所有者或管理员可以分配财务访问权限。', 'Only site owners or administrators can grant finance access.') }}</p><RouterLink :to="{ path: '/collaboration', query: { mode: 'manage', ...(siteId ? { site: String(siteId) } : {}) } }" class="inline-block text-sm text-accent">{{ l('先邀请财务协作者，再配置数据范围', 'Invite a finance collaborator, then set their scope') }} →</RouterLink></template>
  <div class="grid items-start gap-5 xl:grid-cols-[minmax(240px,1fr)_minmax(0,2fr)]">
   <Card class="min-w-0 [&>div]:space-y-3">
    <template v-if="manage"><button v-for="g in grants" :key="g.accessId" class="block w-full rounded-lg border border-border p-3 text-left hover:border-accent disabled:opacity-50" :class="selected === g.accessId ? 'border-accent bg-accent/5' : ''" :disabled="busy" @click="select(g.accessId, g.scope)"><span class="block break-all text-sm font-medium">{{ g.email }}</span><span class="mt-1 block text-xs text-muted">{{ g.revokedAt ? l('邀请已撤销', 'Invite revoked') : !g.acceptedAt ? l('邀请待接受', 'Invite pending') : l('邀请已接受', 'Invite accepted') }} · {{ g.scope?.enabled ? l('已配置范围', 'Scope configured') : l('未启用财务访问', 'Finance access disabled') }}</span></button><p v-if="!grants.length && !busy" class="text-sm text-muted">{{ l('此站点暂无财务协作邀请。', 'No finance collaborators for this site.') }}</p><p v-if="limited" class="text-xs text-muted">{{ l('显示最近 500 条邀请。', 'Showing the latest 500 invitations.') }}</p></template>
    <template v-else><button v-for="s in received" :key="s.accessId" class="block w-full rounded-lg border border-border p-3 text-left hover:border-accent disabled:opacity-50" :class="selected === s.accessId ? 'border-accent bg-accent/5' : ''" :disabled="busy" @click="select(s.accessId, s)"><span class="block break-words text-sm font-medium">{{ s.label }}</span><span class="mt-1 block text-xs text-muted">{{ s.fromDay }} — {{ s.toDay }}</span></button><p v-if="!received.length && !busy" class="text-sm text-muted">{{ l('暂无有效的财务授权。接受协作邀请后，还需要站长单独启用财务范围。', 'No active finance access. After accepting an invitation, the owner must explicitly enable a finance scope.') }}</p><Button v-if="moreScopes" variant="outline" :disabled="busy" @click="action(() => list(true))">{{ l('加载更多', 'Load more') }}</Button></template>
   </Card>
   <div v-if="selected" class="min-w-0 space-y-4">
    <Card v-if="manage && !inactive" class="[&>div]:space-y-4"><h2 class="font-semibold">{{ l('授权范围', 'Access scope') }}</h2><form class="space-y-4" @submit.prevent="save"><fieldset :disabled="busy" class="min-w-0 space-y-4"><Field :label="l('共享名称（对协作者可见）', 'Shared label (visible to collaborator)')"><Input v-model="draft.label" required minlength="3" maxlength="120" /></Field><div class="grid gap-3 sm:grid-cols-2"><Field :label="l('开始日期', 'Start date')"><Input v-model="draft.fromDay" type="date" required /></Field><Field :label="l('结束日期（最多 92 天）', 'End date (up to 92 days)')"><Input v-model="draft.toDay" type="date" required /></Field><Field :label="l('渠道编号（可选）', 'Channel ID (optional)')"><Input v-model="draft.channelId" maxlength="256" /></Field><Field :label="l('模型名称（可选）', 'Model name (optional)')"><Input v-model="draft.model" maxlength="256" /></Field></div><p class="text-xs text-muted">{{ l('日期按北京时间计算；渠道与模型精确匹配，留空表示全部。日期范围固定，到期续期时请重新设置。', 'Dates use Asia/Shanghai. Channel and model match exactly; blank includes all. The date range is fixed and must be updated for a new period.') }}</p><div class="grid gap-3 sm:grid-cols-2"><label v-for="[key, title] in fields" :key="key" class="flex items-center gap-2 text-sm"><input v-model="draft[key]" type="checkbox" />{{ title }}</label></div><label class="flex items-center gap-2 text-sm"><input v-model="draft.enabled" type="checkbox" />{{ l('启用财务访问', 'Enable finance access') }}</label><p class="text-xs leading-6 text-muted">{{ l('此授权允许查看指定范围内的汇总；不会授予站点管理权。每次保存生成新版本，旧版复核仅由站长留存。', 'This grants summaries within the selected scope, without site management rights. Saving creates a new version; only the owner retains earlier reviews.') }}</p><Button type="submit" :loading="busy">{{ l('保存财务授权', 'Save finance scope') }}</Button></fieldset></form></Card>
    <p v-if="inactive" class="text-sm text-muted">{{ l('邀请已撤销或到期，仅保留站长复核记录。', 'The invitation is revoked or expired. Owner review history remains available.') }}</p>
    <Card v-if="report" class="[&>div]:space-y-4"><div class="flex flex-wrap justify-between gap-3"><h2 class="break-words font-semibold">{{ report.scope.label }}</h2><Button variant="outline" size="sm" :disabled="busy" @click="action(loadReport)">{{ l('刷新已采集数据', 'Refresh collected data') }}</Button></div><p class="text-xs text-muted">{{ report.scope.fromDay }} — {{ report.scope.toDay }} · {{ l('北京时间', 'Asia/Shanghai') }} · v{{ report.scope.version }}</p><p class="text-xs text-muted">{{ l('渠道', 'Channel') }}: {{ report.scope.channelId || l('全部', 'All') }} · {{ l('模型', 'Model') }}: {{ report.scope.model || l('全部', 'All') }}</p><div class="grid gap-3 sm:grid-cols-2"><div class="rounded border border-border p-3"><p class="text-xs text-muted">{{ l('已观测扣费', 'Observed charges') }}</p><p class="mt-1 text-xl font-semibold">{{ amount(report.chargeUsd) }} <small class="text-xs">USD</small></p><p class="mt-1 text-xs text-muted">{{ report.pricedRecords }}/{{ report.records }} {{ l('条包含金额', 'records priced') }}</p></div><div v-if="report.scope.costs" class="rounded border border-border p-3"><p class="text-xs text-muted">{{ l('已观测上游成本', 'Observed supplier cost') }}</p><p class="mt-1 text-xl font-semibold">{{ amount(report.supplierCostUsd) }} <small class="text-xs">USD</small></p><p class="mt-1 text-xs text-muted">{{ report.costRecords }}/{{ report.records }} {{ l('条包含成本', 'records with cost') }}</p></div></div><p class="text-xs leading-6 text-muted">{{ l('缺少数据不能视为零消费。本轮读取完整仅表示当前来源读取完成，不保证包含全部业务请求。金额来自日志，不代表银行账单。', 'Missing evidence does not mean zero usage. A complete scan describes the current source, which may not cover all requests. Log amounts are not bank statements.') }}</p><div class="flex flex-wrap gap-2"><Button v-if="current?.details" variant="outline" :disabled="busy" @click="loadRecords()">{{ l('查看授权明细', 'View permitted records') }}</Button><Button v-if="current?.export" variant="outline" :disabled="busy" @click="exportCsv">{{ l('导出每日汇总', 'Export daily summary') }}</Button></div><details class="rounded border border-border p-3"><summary class="cursor-pointer text-sm">{{ l('每日金额与覆盖情况', 'Daily amounts and coverage') }}</summary><div class="mt-3 space-y-2"><div v-for="d in report.days" :key="d.day" class="space-y-1 border-t border-border pt-2 text-xs"><div class="flex flex-wrap justify-between gap-2"><span>{{ d.day }} · {{ label(d.scanStatus) }}</span><span>{{ amount(d.chargeUsd) }} USD · {{ d.pricedRecords }}/{{ d.records }}</span></div><p class="text-muted">{{ d.sourceScope ? label(d.sourceScope) : '—' }} · {{ d.collectedAt ? d.collectedAt + ' UTC' : l('无采集时间', 'No collection time') }}</p></div></div></details></Card>
    <Card v-if="showRecords" class="[&>div]:space-y-3"><h2 class="font-semibold">{{ l('授权范围内的消费明细', 'Permitted consumption records') }}</h2><p class="text-xs text-muted">{{ l('每次读取当前采集批次；重新采集期间请刷新明细。', 'Each read uses the current collection generation. Refresh records during a new scan.') }}</p><p v-if="!records.length" class="text-sm text-muted">{{ l('暂无符合范围的消费记录。', 'No consumption records in this scope.') }}</p><article v-for="r in records" :key="r.id" class="space-y-1 rounded border border-border p-3 text-xs"><p class="break-words">{{ r.day }} · {{ r.model || '—' }} · {{ r.channelId || '—' }}</p><p>{{ l('扣费', 'Charge') }} {{ amount(r.charge) }} USD <span v-if="current?.costs"> · {{ l('成本', 'Cost') }} {{ amount(r.supplierCost) }} USD</span></p></article><Button v-if="moreRecords" variant="outline" :disabled="busy" @click="loadRecords(true)">{{ l('更多明细', 'More records') }}</Button></Card>
    <Card v-if="current && (manage || current.review)" class="[&>div]:space-y-4"><h2 class="font-semibold">{{ l('复核记录', 'Review history') }}</h2><p v-if="!reviews.length" class="text-sm text-muted">{{ l('当前范围暂无复核记录。', 'No reviews for this scope.') }}</p><form v-if="!manage && current.review" class="space-y-3" @submit.prevent="submit"><Field :label="l('复核说明（对站长可见）', 'Review note (visible to owner)')"><textarea v-model="submitNote" class="min-h-24 w-full rounded border border-border bg-bg/60 p-3 text-sm" required minlength="5" maxlength="2000" :disabled="busy" /></Field><Button type="submit" :disabled="busy || reviews.some(r => r.status === 'submitted')">{{ l('提交快照供站长复核', 'Submit snapshot for owner review') }}</Button></form><article v-for="r in reviews" :key="r.id" class="space-y-3 rounded border border-border p-3"><p class="text-sm font-medium">{{ label(r.status) }} · v{{ r.scopeVersion }}</p><p class="text-xs text-muted">{{ r.createdAt }} UTC · {{ r.report.scope.fromDay }} — {{ r.report.scope.toDay }}</p><p class="text-sm">{{ l('提交时扣费', 'Charges at submission') }} {{ amount(r.report.chargeUsd) }} USD · {{ r.report.pricedRecords }}/{{ r.report.records }}</p><p v-if="r.report.scope.costs" class="text-sm">{{ l('提交时成本', 'Cost at submission') }} {{ amount(r.report.supplierCostUsd) }} USD</p><p class="whitespace-pre-wrap break-words text-sm">{{ r.note }}</p><p v-if="r.decision" class="whitespace-pre-wrap break-words text-sm text-muted">{{ l('站长意见', 'Owner decision') }}: {{ r.decision }}</p><RouterLink v-if="manage && r.status === 'accepted' && r.report.scope.costs && Number(r.report.supplierCostUsd) > 0" :to="{path:'/settlements',query:{mode:'manage',source:String(r.id)}}" class="inline-block text-sm text-accent">{{ l('引用此成本快照创建结算草稿', 'Create a statement draft from this cost snapshot') }}</RouterLink><form v-if="manage && r.status === 'submitted'" class="space-y-3" @submit.prevent="decide(r, 'accepted')"><Field :label="l('处理意见（对协作者可见）', 'Decision note (visible to collaborator)')"><textarea v-model="decisions[r.id]" class="min-h-20 w-full rounded border border-border bg-bg/60 p-3 text-sm" required minlength="5" maxlength="2000" :disabled="busy" /></Field><div class="flex gap-2"><Button type="submit" :disabled="busy">{{ l('确认复核', 'Accept review') }}</Button><Button variant="outline" :disabled="busy || (decisions[r.id]?.trim().length ?? 0) < 5" @click="decide(r, 'returned')">{{ l('退回补充', 'Return for follow-up') }}</Button></div></form></article><Button v-if="moreReviews" variant="outline" :disabled="busy" @click="action(() => loadReviews(true))">{{ l('更早记录', 'Older reviews') }}</Button></Card>
   </div>
   <EmptyState v-else :title="l('选择一条财务授权', 'Select finance access')" :description="l('已有协作身份不会自动获得财务数据权限。', 'Existing collaboration roles do not automatically grant financial data access.')" />
  </div>
 </div>
</template>
